export type IconProps = SVGProps<SVGSVGElement> & {
  size?: number | string;
  title?: ReactNode;
};

function makeIcon(viewBox: string, children: ReactNode) {
  return function Icon({ size = "1em", className, style, title, ...rest }: IconProps) {
    return (
      <svg
        xmlns="http://www.w3.org/2000/svg"
        viewBox={viewBox}
        {...rest}
        className={className}
        style={{ verticalAlign: "-0.125em", ...style }}
        width={size}
        height={size}
        fill="currentColor"
        aria-hidden={title ? undefined : true}
        role={title ? "img" : undefined}
      >
        {title ? <title>{title}</title> : null}
        {children}
      </svg>
    );
  };
}

